import { test, expect } from '@playwright/test';

test.describe('File Download Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should trigger file download when export button is clicked', async ({ page }) => {
    const [download] = await Promise.all([
      page.waitForEvent('download'),
      page.getByRole('button', { name: /export/i }).click(),
    ]);
    const downloadPath = await download.path();
    expect(downloadPath).toBeTruthy();
  });

  test('should show success message after clicking export button', async ({ page }) => {
    await page.getByRole('button', { name: /export/i }).click();
    const successMessage = await page.getByText(/download initiated/i);
    await expect(successMessage).toBeVisible();
  });
});
